void queue_event ( struct s_smc * smc , int class ) int event { PRINTF ( "queue class %d event %d\n" , class , event ) ; smc -> q . ev_put -> class = class ; smc -> q . ev_put -> event = event ; if ( ++ smc -> q . ev_put == & smc -> q . ev_queue [ MAX_EVENT ] ) { smc -> q . ev_put = smc -> q . ev_queue ; } if ( smc -> q . ev_put == smc -> q . ev_get ) { SMT_ERR_LOG ( smc , SMT_E0137 , 0 ) ; } } ; 